import { generateProblem, templates } from "../math/engine";
import type { SemanticFigure } from "../math/contracts";
import { lessons } from "./lessons";
import { skills } from "../curriculum/catalog";
import { displayAnswer } from "../math/polish";
import { methods } from "./problem-methods";
import { principles } from "./problem-principles";

/** One short lesson per problem type: what is given, what to find, how to
 * solve it, and a worked instance generated by the same template. */
export type ProblemLessonView = {
  templateId: string;
  title: string;
  goal: string;
  /** The named property or definition the method rests on. */
  principle: string | null;
  terms: { term: string; meaning: string }[];
  method: string[];
  watch: string | null;
  example: {
    prompt: string;
    figure?: SemanticFigure;
    steps: string[];
    answer: string;
  };
};
export type ProblemMethod = {
  /** What the problem gives and what it asks for, in one sentence. */
  goal: string;
  /** Terms the method uses, defined before use. */
  terms?: [string, string][];
  /** The steps that solve every instance of this problem type. */
  method: string[];
  /** The most common error, stated as what to do instead. */
  watch?: string;
};

const byId = new Map(templates.map((template) => [template.id, template]));

export function hasProblemLesson(templateId: string) {
  return byId.has(templateId);
}

/** The example is another instance of the same template, never the problem the
 * learner is working on, so the lesson teaches the method without the answer. */
export function problemLesson(
  templateId: string,
  seed: string,
  avoidPrompt?: string,
): ProblemLessonView {
  const template = byId.get(templateId);
  if (!template) throw new Error(`Unknown problem type ${templateId}`);
  let example = generateProblem(templateId, `${seed}:lesson:0`);
  for (let i = 1; i < 8 && example.public.prompt === avoidPrompt; i++)
    example = generateProblem(templateId, `${seed}:lesson:${i}`);
  const response = example.public.response;
  const answer =
    response.kind === "choice"
      ? (response.options.find((option) => option.id === example.answer)
          ?.label ?? example.answer)
      : skills.find((skill) => skill.id === template.skillId)?.strand ===
          "fractions"
        ? example.answer
        : displayAnswer(example.answer);
  const authored = methods[templateId];
  const reference = lessons.find((lesson) =>
    lesson.templateIds.includes(templateId),
  );
  return {
    templateId,
    title: template.title,
    goal: authored?.goal ?? `${template.description}`,
    principle: principles[templateId] ?? null,
    terms: (authored?.terms ?? []).map(([term, meaning]) => ({
      term,
      meaning,
    })),
    method: authored?.method ?? [example.hint],
    watch: authored?.watch ?? reference?.pitfalls[0] ?? null,
    example: {
      prompt: example.public.prompt,
      ...(example.public.figure ? { figure: example.public.figure } : {}),
      steps: example.explanation,
      answer,
    },
  };
}
